"""Export the configured source tree (EXPORT_SOURCE): exactly the files this
configuration compiles, its generated config header and linker script, and a
Makefile that rebuilds the same binary without mimiconf. RP boards get the
CMake project and the exact build command instead."""
from __future__ import annotations

import glob
import shutil
from pathlib import Path

from .model import ROOT, Config

MAKE_HEADER = """# MimiBoot-Mu {board} ({chip}): the sources this configuration compiles, nothing else.
# Generated by mimiconf.py. Rebuild with GNU make (Linux, macOS, WSL, MSYS2):
#     make                 # or: make CROSS=/path/to/{cross}
# Change features in the original tree (python mimiconf.py) and export again;
# {config} is generated, don't edit it by hand.
"""


def _copy(rel: str, dst: Path):
    s = ROOT / rel
    d = dst / rel
    d.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(s, d)


def _files(recipe: dict) -> list[str]:
    files = list(recipe["sources"])
    for pattern in recipe.get("headers", []):
        for hit in sorted(glob.glob(str(ROOT / pattern))):
            files.append(Path(hit).relative_to(ROOT).as_posix())
    return sorted(set(files))


def makefile(cfg: Config, recipe: dict) -> str:
    t = cfg.t
    cross = recipe["cc"].removesuffix("gcc")
    name = recipe["target"]
    cflags = " \\\n         ".join(recipe["cflags"])
    if recipe.get("include"):                                   # AVR: the config header is force-included
        incl = f"-include {recipe['include']} -I."
    else:
        incl = f"-DMB_CONFIG_HEADER='\"{recipe['config']}\"' -I. -Iinclude"
    ld = " ".join(recipe["ldflags"]) + (f" -T{recipe['linker']}" if recipe.get("linker") else "")
    srcs = " \\\n       ".join(recipe["sources"])
    deps = recipe["config"] + (f" {recipe['linker']}" if recipe.get("linker") else "")
    hex_args = " ".join(recipe.get("hex_args", []))
    out = MAKE_HEADER.format(board=t.name, chip=t.chip_name, cross=recipe["cc"], config=recipe["config"])
    out += f"""
CROSS   ?= {cross}
CC      := $(CROSS)gcc
OBJCOPY := $(CROSS)objcopy
SIZE    := $(CROSS)size

CFLAGS  := {cflags} \\
         {incl}
LDFLAGS := {ld} -Wl,-Map={name}.map
SRCS    := {srcs}

all: {name}.hex{'' if recipe.get('include') else f' {name}.bin'}

{name}.elf: $(SRCS) {deps}
\t$(CC) $(CFLAGS) $(SRCS) $(LDFLAGS) -o $@
\t$(SIZE) $@

{name}.bin: {name}.elf
\t$(OBJCOPY) -O binary $< $@

{name}.hex: {name}.elf
\t$(OBJCOPY) -O ihex {hex_args} $< $@

clean:
\trm -f {name}.elf {name}.bin {name}.hex {name}.map

.PHONY: all clean
"""
    return out


def export_source(cfg: Config, out: Path, info: dict) -> Path:
    dst = out / "source"
    if dst.exists():
        shutil.rmtree(dst)
    dst.mkdir(parents=True)
    recipe = info.get("recipe") or {}
    if recipe.get("kind") == "pico":
        for rel in ["CMakeLists.txt", "pico_sdk_import.cmake", "mimiboot_client.cmake", "LICENSE"]:
            if (ROOT / rel).exists():
                _copy(rel, dst)
        for d in ["core", "include", "port/rp2040", "port/rp2350", "client", "tools"]:
            if (ROOT / d).is_dir():
                shutil.copytree(ROOT / d, dst / d, ignore=shutil.ignore_patterns("__pycache__", "*.pyc"))
        for f in ("mimiboot_config.h", "keys.h"):
            if (out / f).exists():
                shutil.copy2(out / f, dst / f)
        args = []
        for i, c in enumerate(recipe["command"]):
            if i == 0:
                c = "python"                                    # whatever interpreter ran mimiconf
            elif c.startswith("<output>"):
                rest = c[len("<output>"):].lstrip("/\\")
                c = "build" if rest == "work" else rest         # the header sits next to this file
            elif c.startswith("." + "\\") or c.startswith("./"):
                c = c[2:].replace("\\", "/")
            args.append(f'"{c}"' if " " in c else c)
        cmd = " ".join(args)
        (dst / "BUILD.txt").write_text(
            f"MimiBoot-Mu {cfg.t.name}: the Pico SDK project with this configuration's header.\n\n"
            f"Build (from this folder, with PICO_SDK_PATH set):\n\n    {cmd}\n\n"
            "Paths to the SDK / toolchains in that command are the ones found when it was exported.\n")
        return dst
    for rel in _files(recipe):
        _copy(rel, dst)
    shutil.copy2(out / recipe["config"], dst / recipe["config"])
    if recipe.get("linker"):
        shutil.copy2(out / recipe["linker"], dst / recipe["linker"])
    (dst / "Makefile").write_text(makefile(cfg, recipe), newline="\n")
    lic = ROOT / "LICENSE"
    if lic.exists():
        shutil.copy2(lic, dst / "LICENSE")
    return dst
